// P-OPS2-B BF16 matrix bodies for the integrated operation compiler (new code in this lane).
//
// Operand staging, fragment formation and the per-element arithmetic are those of the P-OPS-C small-tile body
// (popsc_mm.cuh, P-OPS-C 0ebaf7394, itself reusing the pinned Latch v0.6.0 bgemm.cuh helpers unchanged). Each output
// element owns one FP32 accumulator from +0 that receives one mma.sync.m16n8k16 per k16 block in ascending k and is
// rounded once with cvt.rn.bf16x2 (s101h::bpk). The stored BF16 bits are therefore identical to popsc::btile.
//
// Added here, both generated by the compiler from captured operations:
//  * Operand prologue (PA/PB): a BF16 operand that is an elementwise cast of FP32 values (weights, normalized or
//    attended activations) is computed while staging: the functor returns the identical FP32 expression for the
//    operand's flat element index and staging rounds it with __float2bfloat16_rn, exactly as the separate cast
//    phase would. The bytes reaching shared memory equal the materialized BF16 operand. Prologue loads for stage
//    it+NST-1 are issued after the stage-it barrier and committed to shared memory after stage it's MMAs.
//  * Epilogue: elementwise consumers reading the BF16 product at the same flat index receive the rounded and widened
//    value (what a load of the stored result yields). STORE=false omits the product store when nothing else reads it.
#pragma once
#include "popsc_mm.cuh"

namespace pops2b {

using s101h::bf16;

struct NoEpi {
  static constexpr bool kTile = false;
  template <int BM, int BN> __host__ __device__ static constexpr int ebytes() { return 0; }
  DEV void operator()(unsigned, float, float) const {}
  template <int BM, int BN> DEV void prefetch(char*, unsigned, unsigned) const {}
  template <int BM, int BN> DEV void tile(const float*, int, const char*, unsigned, unsigned) const {}
};
struct NoPro {
  static constexpr bool kStaged = false;
  template <int R, bool RK, int KS> __host__ __device__ static constexpr int bytes() { return 0; }
  template <int R, bool RK, int KS>
  DEV void issue(char*, long long, long long, long long, int, int) const {}
  template <int R, bool RK, int KS>
  DEV void convert(const char*, bf16*, bf16*, long long, long long, long long, int, int) const {}
};

// Shared-memory staging geometry of one prologue source (element type T) for an R x KS (RK) or KS x R operand stage:
// rows padded by 16 bytes like the BF16 operand stages.
template <class T, int R, bool RK, int KS>
struct Src {
  static constexpr int PAD = 16 / (int)sizeof(T);
  static constexpr int EL = RK ? R * (KS + PAD) : KS * (R + PAD);
  static constexpr int BYTES = (EL * (int)sizeof(T) + 15) / 16 * 16;
  static DEV int pos(int r, int kk) { return RK ? r * (KS + PAD) + kk : kk * (R + PAD) + r; }
};

// cp.async one source stage: element (r, kk) of the operand tile is X[off + (r0 + r) * sr + (k + kk) * sk].
template <class T, int R, bool RK, int KS>
DEV void sstage(const T* __restrict__ X, long long sr, long long sk, int r0, int k, T* __restrict__ S) {
  constexpr int V = 16 / (int)sizeof(T);                 // elements per 16-byte chunk along the contiguous dim
  constexpr int CH = R * KS / V;
#pragma unroll
  for (int c0 = 0; c0 < CH; c0 += NTHREADS) {
    const int c = c0 + threadIdx.x;
    if (CH % NTHREADS == 0 || c < CH) {
      if (RK) {
        const int r = c / (KS / V), kc = (c % (KS / V)) * V;
        s101h::cpa16(reinterpret_cast<float*>(S + Src<T, R, RK, KS>::pos(r, kc)),
                     reinterpret_cast<const float*>(X + (long long)(r0 + r) * sr + (k + kc)));
      } else {
        const int kr = c / (R / V), rc = (c % (R / V)) * V;
        s101h::cpa16(reinterpret_cast<float*>(S + Src<T, R, RK, KS>::pos(rc, kr)),
                     reinterpret_cast<const float*>(X + (long long)(k + kr) * sk + r0 + rc));
      }
    }
  }
}

// Epilogue operand prefetch: one BM x BN tile of a row-major operand (row stride ldc elements) copied by cp.async into
// a dense [BM][BN] shared-memory block at tile start, so the generated epilogue reads it without global latency.
template <class T, int BM, int BN>
__host__ __device__ constexpr int epi_bytes() { return (BM * BN * (int)sizeof(T) + 15) / 16 * 16; }

template <class T, int BM, int BN>
DEV void epi_prefetch(const T* __restrict__ src, unsigned ldc, T* __restrict__ dst) {
  constexpr int V = 16 / (int)sizeof(T), CPR = BN / V, CH = BM * CPR;
#pragma unroll
  for (int c0 = 0; c0 < CH; c0 += NTHREADS) {
    const int c = c0 + threadIdx.x;
    if (CH % NTHREADS == 0 || c < CH) {
      const int r = c / CPR, cc = (c % CPR) * V;
      s101h::cpa16(reinterpret_cast<float*>(dst + r * BN + cc), reinterpret_cast<const float*>(src + (size_t)r * ldc + cc));
    }
  }
}

// Store one converted pair of adjacent (along the contiguous dimension) BF16 operand elements to the stage slot.
template <int R, bool RK, int KS>
DEV void put_pair(bf16* __restrict__ dst, int r, int kk, uint32_t packed) {
  if (RK) *reinterpret_cast<uint32_t*>(dst + r * (KS + 8) + kk) = packed;
  else *reinterpret_cast<uint32_t*>(dst + kk * (R + 8) + r) = packed;
}

template <int BM, int BN, int WM, int WN, bool AK, bool BKC, int KS, int NST, bool STORE, bool PA, bool PB,
          class Epi, class ProA, class ProB>
DEV void btile2(const popsc::BArgs& g, long long aoff, long long boff, bf16* aout, bf16* bout, int b, int m0, int n0,
                bf16* S, const Epi& epi, const ProA& pa, const ProB& pb) {
  using L = popsc::BLay<BM, BN, AK, BKC, KS>;
  constexpr int WTM = BM / WM, WTN = BN / WN, MT = WTM / 16, NT = WTN / 8;
  static_assert(WM * WN == NTHREADS / 32 && WTM % 16 == 0 && WTN % 8 == 0 && (NT == 1 || NT % 2 == 0), "warp tile");
  static_assert(NST >= 2, "stage ring");
  const int lane = threadIdx.x & 31, w = threadIdx.x >> 5, gq = lane >> 2, tq = lane & 3;
  const int wm0 = (w / WN) * WTM, wn0 = (w % WN) * WTN;
  const bf16* A = g.A + (long long)b * g.bsa;
  const bf16* B = g.B + (long long)b * g.bsb;
  const long long ao = aoff + (long long)b * g.bsa, bo = boff + (long long)b * g.bsb;
  float acc[MT][NT][4];
#pragma unroll
  for (int i = 0; i < MT; ++i)
#pragma unroll
    for (int j = 0; j < NT; ++j)
#pragma unroll
      for (int q = 0; q < 4; ++q) acc[i][j][q] = 0.f;
  // Stage = [A bf16][B bf16][A prologue sources][B prologue sources]; prologue operands are converted from their
  // staged sources into the stage's BF16 slot right before that stage's MMAs.
  constexpr int AB = (L::STAGE * 2 + 15) / 16 * 16;
  constexpr int SA_BYTES = ProA::template bytes<BM, AK, KS>(), SB_BYTES = ProB::template bytes<BN, BKC, KS>();
  constexpr int STAGE_BYTES = AB + SA_BYTES + SB_BYTES;
  char* const base = reinterpret_cast<char*>(S);
  // Each materialized operand element is written by exactly one task: stage it of the A operand by the tile whose
  // column index equals it modulo the column-tile count (B: row index), spreading the stores over the grid.
  const int tcol = n0 / BN, ncol = g.N / BN, trow = m0 / BM, nrow = g.M / BM;
  const int nk = g.K / KS;
  char* const E = base + NST * STAGE_BYTES;                        // epilogue operand prefetch region
  const unsigned ebase = (unsigned)((long long)b * g.bsc + (long long)m0 * g.ldc + n0);
  if constexpr (Epi::kTile) epi.template prefetch<BM, BN>(E, ebase, (unsigned)g.ldc);  // joins the first cp.async group
  auto issue = [&](int kk, int st) {
    char* stage = base + st * STAGE_BYTES;
    bf16* As = reinterpret_cast<bf16*>(stage);
    if constexpr (!PA) popsc::bstage<BM, AK, KS>(A, g.sam, g.sak, m0, kk, As);
    else pa.template issue<BM, AK, KS>(stage + AB, ao, g.sam, g.sak, m0, kk);
    if constexpr (!PB) popsc::bstage<BN, BKC, KS>(B, g.sbn, g.sbk, n0, kk, As + L::A_EL);
    else pb.template issue<BN, BKC, KS>(stage + AB + SA_BYTES, bo, g.sbn, g.sbk, n0, kk);
  };
#pragma unroll
  for (int s = 0; s < NST - 1; ++s) {
    if (s < nk) issue(s * KS, s);
    s101h::cpa_commit();
  }
#pragma unroll 1
  for (int it = 0; it < nk; ++it) {
    s101h::cpa_wait<NST - 2>();
    __syncthreads();                                               // stage it landed; stage it-1 fully consumed
    if constexpr (PA || PB) {
      char* stage = base + (it % NST) * STAGE_BYTES;
      bf16* As = reinterpret_cast<bf16*>(stage);
      if constexpr (PA) pa.template convert<BM, AK, KS>(stage + AB, As, (aout != nullptr && it % ncol == tcol) ? aout : nullptr,
                                                        ao, g.sam, g.sak, m0, it * KS);
      if constexpr (PB) pb.template convert<BN, BKC, KS>(stage + AB + SA_BYTES, As + L::A_EL,
                                                         (bout != nullptr && it % nrow == trow) ? bout : nullptr,
                                                         bo, g.sbn, g.sbk, n0, it * KS);
      __syncthreads();                                             // converted BF16 operands visible
    }
    if (it + NST - 1 < nk) issue((it + NST - 1) * KS, (it + NST - 1) % NST);
    s101h::cpa_commit();
    const bf16* As = reinterpret_cast<const bf16*>(base + (it % NST) * STAGE_BYTES);
    const bf16* Bs = As + L::A_EL;
#pragma unroll
    for (int k16 = 0; k16 < KS; k16 += 16) {
      uint32_t af[MT][4];
#pragma unroll
      for (int i = 0; i < MT; ++i) {
        if (AK) s101h::bldsm4(af[i], As + (wm0 + 16 * i + (lane & 15)) * (KS + 8) + k16 + (lane >> 4) * 8);
        else s101h::bldsm4t(af[i], As + (k16 + (lane & 7) + ((lane >> 4) << 3)) * (BM + 8) + wm0 + 16 * i +
                                       (((lane >> 3) & 1) << 3));
      }
      if constexpr (NT == 1) {
        uint32_t bb[2];
        if (BKC) popsc::bldsm2(bb, Bs + (wn0 + (lane & 7)) * (KS + 8) + k16 + ((lane >> 3) & 1) * 8);
        else popsc::bldsm2t(bb, Bs + (k16 + (lane & 7) + ((lane >> 3) & 1) * 8) * (BN + 8) + wn0);
#pragma unroll
        for (int i = 0; i < MT; ++i) s101h::bmma(acc[i][0], af[i][0], af[i][1], af[i][2], af[i][3], bb[0], bb[1]);
      } else {
#pragma unroll
        for (int j = 0; j < NT; j += 2) {
          uint32_t bb[4];
          if (BKC) s101h::bldsm4(bb, Bs + (wn0 + 8 * (j + (lane >> 4)) + (lane & 7)) * (KS + 8) + k16 + ((lane >> 3) & 1) * 8);
          else s101h::bldsm4t(bb, Bs + (k16 + (lane & 7) + ((lane >> 3) & 1) * 8) * (BN + 8) + wn0 + 8 * (j + (lane >> 4)));
#pragma unroll
          for (int i = 0; i < MT; ++i) {
            s101h::bmma(acc[i][j], af[i][0], af[i][1], af[i][2], af[i][3], bb[0], bb[1]);
            s101h::bmma(acc[i][j + 1], af[i][0], af[i][1], af[i][2], af[i][3], bb[2], bb[3]);
          }
        }
      }
    }
  }
  s101h::cpa_wait<0>();
  bf16* C = g.C + (long long)b * g.bsc;
  const unsigned cbase = (unsigned)((long long)b * g.bsc);
  constexpr int LDT = BN + 4;                                      // FP32 tile staging (row-major, padded)
  float* T = reinterpret_cast<float*>(S);
  static_assert(!Epi::kTile || BM * LDT * 4 <= NST * STAGE_BYTES, "tile staging fits the stage ring");
  if constexpr (Epi::kTile) __syncthreads();                       // every warp finished reading the stage ring
#pragma unroll
  for (int i = 0; i < MT; ++i)
#pragma unroll
    for (int j = 0; j < NT; ++j) {
      const int m = m0 + wm0 + 16 * i + gq, n = n0 + wn0 + 8 * j + 2 * tq;
#pragma unroll
      for (int h = 0; h < 2; ++h) {
        const int mm = m + 8 * h;
        const uint32_t packed = s101h::bpk(acc[i][j][2 * h], acc[i][j][2 * h + 1]);
        if constexpr (STORE) *reinterpret_cast<uint32_t*>(C + (long long)mm * g.ldc + n) = packed;
        const __nv_bfloat162 pair = *reinterpret_cast<const __nv_bfloat162*>(&packed);
        if constexpr (Epi::kTile) {
          *reinterpret_cast<float2*>(T + (mm - m0) * LDT + (n - n0)) =
              make_float2(__bfloat162float(pair.x), __bfloat162float(pair.y));
        } else {
          epi(cbase + (unsigned)((long long)mm * g.ldc + n), __bfloat162float(pair.x), __bfloat162float(pair.y));
        }
      }
    }
  if constexpr (Epi::kTile) {
    __syncthreads();
    epi.template tile<BM, BN>(T, LDT, E, ebase, (unsigned)g.ldc);
  }
  __syncthreads();                                                 // every fragment/tile read done before smem reuse
}

template <int BM, int BN, int WM, int WN, bool AK, bool BKC, int KS, int NST, bool STORE, bool PA, bool PB,
          class Epi, class ProA, class ProB>
__device__ __noinline__ void bmm_phase2(const popsc::BArgs g, float* smem, const Epi epi, const ProA pa,
                                        const ProB pb, long long aoff, long long boff, bf16* aout, bf16* bout,
                                        int lo = 0, int hi = 1, int den = 1, int rot = 0) {
  const popsc::Slice s = popsc::slice_of(lo, hi, den, rot);
  if ((int)blockIdx.x < s.first || (int)blockIdx.x >= s.first + s.count) return;
  const int tm = g.M / BM, tn = g.N / BN, ntask = g.nb * tm * tn;
  bf16* S = reinterpret_cast<bf16*>(smem);
  for (int task = s.me; task < ntask; task += s.count) {
    const int j = task % tn, r = task / tn;
    btile2<BM, BN, WM, WN, AK, BKC, KS, NST, STORE, PA, PB, Epi, ProA, ProB>(g, aoff, boff, aout, bout, r / tm,
                                                                           (r % tm) * BM, j * BN, S, epi, pa, pb);
  }
}

}  // namespace pops2b
